import { ToggleGroup } from '@refy-design/web';
import type { ComponentProps } from 'react';
const layers = [
  { value: 'critical', label: 'Critical' },
  { value: 'notices', label: 'Warnings' },
  { value: 'resolved', label: 'Resolved' },
  { value: 'info', label: 'Info' },
];
export function Example() {
  const args: Pick<
    ComponentProps<typeof ToggleGroup>,
    'options' | 'label' | 'defaultValue'
  > = { options: layers, label: 'Layers', defaultValue: ['critical', 'notices'] };
  return <ToggleGroup {...args} />;
}

import { ToggleGroup } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
const layers = [
  { value: 'critical', label: 'Critical' },
  { value: 'notices', label: 'Warnings' },
  { value: 'resolved', label: 'Resolved' },
  { value: 'info', label: 'Info' },
];
export function Example() {
  const args: Pick<ComponentProps<typeof ToggleGroup>, 'options' | 'label'> = {
    options: layers,
    label: 'Layers',
  };
  const [values, setValues] = useState<string[]>(['critical']);
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 12,
        alignItems: 'flex-start',
      }}
    >
      <ToggleGroup {...args} value={values} onChange={setValues} />
      <code
        style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--ink-3)' }}
      >
        [{values.join(', ') || 'empty'}]
      </code>
    </div>
  );
}

import { ToggleGroup } from '@refy-design/web';
import type { ComponentProps } from 'react';
const layers = [
  { value: 'critical', label: 'Critical' },
  { value: 'notices', label: 'Warnings' },
  { value: 'resolved', label: 'Resolved' },
  { value: 'info', label: 'Info' },
];
export function Example() {
  const args: Pick<
    ComponentProps<typeof ToggleGroup>,
    'options' | 'label' | 'defaultValue' | 'disabled'
  > = {
    options: layers,
    label: 'Layers unavailable',
    defaultValue: ['critical'],
    disabled: true,
  };
  return <ToggleGroup {...args} />;
}
